/* ---------- Per-test educational notes ----------
   p: principle · r: reagents/materials · q: quality control · i: clinical interpretation · ref: REFS ids */
const EDU={
'Venous blood collection (phlebotomy)':{p:'Pre-analytical quality starts at the bedside: correct identification, correct tube and order of draw, minimal venous stasis and correct mixing prevent most laboratory errors, which occur mainly in the pre-analytical phase.',r:['Vacuum tubes (citrate, serum, heparin, EDTA, fluoride)','Needles 21–22 G and holders; tourniquet','70% isopropyl alcohol swabs; gauze; sharps container','Gloves and labels'],q:['Two-identifier patient identification before every draw','Tourniquet ≤ 1 minute; avoid fist pumping','Follow the order of draw; invert tubes the stated number of times','Label at the bedside and record collection time'],i:['Prolonged tourniquet or fist clenching falsely raises potassium and protein-bound analytes','EDTA carry-over falsely raises potassium and lowers calcium and ALP'],ref:['who_phleb','clsi_gp41']},
'Specimen rejection criteria':{p:'Results are only as reliable as the specimen. Defined rejection criteria protect patients from results produced on unsuitable samples.',r:['Laboratory rejection policy and log','Haemolysis/icterus/lipaemia indices on analysers'],q:['Record every rejection with reason, time and person informed','Audit rejection rates by ward as a quality indicator'],i:['Haemolysis falsely raises K⁺, LDH, AST, phosphate and magnesium','A clotted EDTA tube gives falsely low platelet and WBC counts','An under-filled citrate tube prolongs PT and APTT'],ref:['clsi_gp41','tietz']},
'Internal quality control (Westgard)':{p:'Control materials with known target values are analysed with patient samples; their results are plotted on Levey–Jennings charts and judged with multirule (Westgard) criteria that detect random and systematic error while keeping false rejection low.',r:['Commercial control material, at least two levels','Levey–Jennings charts (manual or LIS)'],q:['Establish lab-specific mean and SD from at least 20 runs','Investigate and document every rule violation before releasing results','Participate in external quality assessment'],i:['1-3s and R-4s mainly detect random error','2-2s, 4-1s and 10x mainly detect systematic error (bias, drift)'],ref:['westgard','tietz']},
'Complete blood count (CBC)':{p:'Automated analysers count and size cells by electrical impedance and/or flow cytometric light scatter; haemoglobin is measured photometrically (usually cyanide-free SLS method). MCV and RDW are measured; MCH and MCHC are calculated.',r:['Diluent, lysing reagents and haemoglobin reagent for the analyser','Three-level haematology controls','EDTA (K2) tubes'],q:['Run three control levels daily; check against acceptable ranges','Use delta checks and flags to trigger a blood film review','Check MCHC: a value above about 37 g/dL suggests cold agglutinins, lipaemia or spherocytosis'],i:['↓ Hb with ↓ MCV: iron deficiency, thalassaemia trait, anaemia of chronic disease','↓ Hb with ↑ MCV: B12/folate deficiency, liver disease, alcohol','↑ WBC: infection, inflammation, leukaemia; ↓ WBC: viral infection, marrow failure, benign ethnic neutropenia','↓ Platelets: ITP, DIC, malaria, marrow failure; exclude platelet clumps on the film'],ref:['dacie','hsieh']},
'WBC differential (blood film)':{p:'Romanowsky stains (Leishman, Giemsa, Wright) combine methylene blue/azure B (basic, stains nuclei and acidic cytoplasm blue-purple) and eosin (acidic, stains haemoglobin and eosinophil granules orange-pink). Correct pH (6.8) is essential for balanced colours.',r:['Leishman stain (in methanol) or Giemsa stock','Buffered water pH 6.8','Absolute methanol (for Giemsa)'],q:['Check staining quality on every batch: neutrophil granules lilac, RBCs pink-orange','Count in the monolayer; 100 cells minimum (200 if abnormal)','Compare manual and automated differentials on discrepant results'],i:['Neutrophilia: bacterial infection, steroids, inflammation','Lymphocytosis: viral infections, CLL, pertussis','Eosinophilia: parasites (schistosomiasis, hookworm), allergy, drugs','Left shift or blasts: urgent review by a haematologist'],ref:['dacie','cheesbrough2']},
'Erythrocyte sedimentation rate (ESR, Westergren)':{p:'Red cells sediment faster when plasma fibrinogen and globulins neutralise their negative surface charge (zeta potential), allowing rouleaux formation. Westergren measures the plasma column after 60 minutes.',r:['3.8% (0.109 mol/L) trisodium citrate','Westergren tubes (200 mm) and vertical rack'],q:['Exactly vertical tube, 18–25 °C, no vibration or sunlight','Test within 4 hours of collection','Anaemia raises and polycythaemia lowers ESR: interpret with Hb'],i:['↑ Infection, inflammation, TB, myeloma, pregnancy, anaemia, older age','↓ Polycythaemia, sickle cell disease, spherocytosis, hypofibrinogenaemia'],ref:['icsh_esr','dacie']},
'Reticulocyte count':{p:'Supravital dyes (new methylene blue) precipitate residual ribosomal RNA in young red cells as a blue reticulum, reflecting marrow erythropoietic activity over the last 1–2 days.',r:['New methylene blue solution','Miller ocular disc (optional)'],q:['Count at least 1000 red cells','Correct for anaemia (corrected count / reticulocyte production index)'],i:['↑ Haemolysis, acute bleeding, response to iron/B12/folate therapy','↓ Aplastic anaemia, untreated nutritional deficiency, marrow infiltration, renal failure'],ref:['dacie']},
'Sickling test (sodium metabisulphite)':{p:'Sodium metabisulphite is a reducing agent that deoxygenates haemoglobin. Deoxy-HbS polymerises and distorts red cells into sickle or holly-leaf shapes.',r:['2% sodium metabisulphite, freshly prepared','Petroleum jelly, slides, coverslips'],q:['Run known positive (AS or SS) and negative controls','Use fresh reagent: old reagent gives false negatives'],i:['Positive in sickle trait (AS), sickle cell disease (SS) and compound states (SC, Sβ)','Cannot distinguish AS from SS: confirm by electrophoresis or HPLC'],ref:['dacie','cheesbrough2']},
'Iron studies':{p:'Serum iron is measured colorimetrically after release from transferrin; TIBC reflects transferrin; ferritin (immunoassay) reflects body iron stores but is also an acute-phase protein.',r:['Iron colour reagent (e.g. ferrozine), TIBC saturation reagent','Ferritin immunoassay reagents and calibrators'],q:['Morning sample (diurnal variation of serum iron)','Avoid haemolysis','Run two-level controls'],i:['Iron deficiency: ↓ ferritin, ↓ iron, ↑ TIBC, ↓ saturation','Anaemia of chronic disease: normal/↑ ferritin, ↓ iron, ↓ TIBC','Iron overload: ↑ ferritin and ↑ saturation (> 45% suggests haemochromatosis)'],ref:['dacie','tietz']},
'Vitamin B12 and folate':{p:'Competitive-binding immunoassays (chemiluminescence) measure serum B12 and folate; red cell folate reflects longer-term status.',r:['B12 and folate immunoassay reagents, calibrators, controls'],q:['Protect from light; avoid haemolysis (red cells contain folate)','Interpret borderline B12 with methylmalonic acid or homocysteine where available'],i:['↓ B12: pernicious anaemia, malabsorption, vegan diet, metformin, PPI use','↓ Folate: poor diet, alcohol, pregnancy, haemolysis, methotrexate','Both cause megaloblastic anaemia; B12 deficiency also causes neuropathy'],ref:['dacie','tietz']},
'Prothrombin time (PT / INR)':{p:'Thromboplastin (tissue factor + phospholipid) and calcium are added to citrated plasma to activate the extrinsic and common pathways (factors VII, X, V, II, fibrinogen). The INR standardises PT for warfarin monitoring using the reagent ISI.',r:['Thromboplastin reagent with known ISI','Normal and abnormal control plasmas','3.2% sodium citrate tubes'],q:['Correct 9:1 blood:citrate ratio; reject under-filled tubes','Establish the geometric mean normal PT for each reagent lot','Run normal and abnormal controls each shift'],i:['Prolonged: warfarin, vitamin K deficiency, liver disease, DIC, factor VII deficiency','INR is validated for warfarin, not for liver disease severity on its own'],ref:['dacie']},
'Activated partial thromboplastin time (APTT)':{p:'Contact activator (silica, kaolin or ellagic acid) plus phospholipid activates the intrinsic pathway (XII, XI, IX, VIII) and the common pathway; calcium starts clotting.',r:['APTT reagent (activator + phospholipid)','0.025 mol/L calcium chloride','Normal and abnormal control plasmas'],q:['Test within 4 hours (heparin samples within 1 hour)','Each laboratory sets its own reference interval and heparin range'],i:['Prolonged: haemophilia A/B, von Willebrand disease, heparin, lupus anticoagulant, DIC, liver disease','A 50:50 mix that corrects suggests factor deficiency; no correction suggests an inhibitor'],ref:['dacie']},
'Fibrinogen (Clauss) and D-dimer':{p:'Clauss: with excess thrombin, the clotting time of diluted plasma is inversely proportional to fibrinogen concentration. D-dimer immunoassays detect cross-linked fibrin degradation products.',r:['High-concentration thrombin reagent; fibrinogen calibrator','D-dimer latex/immunoturbidimetric reagent'],q:['Use calibration curves for each reagent lot','Report D-dimer units clearly (FEU or DDU)'],i:['↓ Fibrinogen: DIC, liver failure, thrombolysis, inherited deficiency','↑ D-dimer: thrombosis, DIC, surgery, infection, pregnancy, older age','A normal D-dimer with low clinical probability helps exclude venous thromboembolism'],ref:['dacie']},
'Blood glucose (fasting and random)':{p:'Enzymatic methods: glucose oxidase (with peroxidase and a chromogen) or hexokinase/G6PD (NADPH measured at 340 nm, the reference principle).',r:['Glucose oxidase–peroxidase or hexokinase reagent','Glucose calibrator and controls','Fluoride-oxalate tubes'],q:['Separate or use fluoride promptly: glycolysis lowers glucose about 5–7% per hour','Run two-level controls each run'],i:['Diabetes: fasting ≥ 7.0 mmol/L, or random ≥ 11.1 mmol/L with symptoms (confirm per ADA criteria)','Hypoglycaemia < 3.9 mmol/L; critical values phone the clinician'],ref:['ada','tietz']},
'Oral glucose tolerance test (OGTT)':{p:'A standard 75 g glucose load tests the ability to clear glucose; the 2-hour value classifies glucose tolerance. In pregnancy, one-step 75 g OGTT uses fasting, 1-hour and 2-hour thresholds.',r:['75 g anhydrous glucose (82.5 g monohydrate)','Fluoride tubes'],q:['Standardise preparation: ≥ 3 days normal carbohydrate intake, overnight fast 8–14 h, seated rest, no smoking'],i:['2-h glucose 7.8–11.0 mmol/L: impaired glucose tolerance; ≥ 11.1: diabetes','Gestational diabetes if any value ≥ 5.1 (fasting), 10.0 (1 h) or 8.5 (2 h) mmol/L'],ref:['ada','iadpsg']},
'HbA1c (glycated haemoglobin)':{p:'Glucose binds non-enzymatically to the N-terminal valine of the β-chain; HbA1c reflects average glycaemia over the preceding 2–3 months (red cell lifespan). Measured by HPLC, immunoassay or enzymatic methods traceable to IFCC/NGSP.',r:['HPLC buffers and columns, or immunoassay reagents','NGSP/IFCC-traceable calibrators and controls'],q:['Use certified methods; review chromatograms for variants (HbS, HbC, HbF)'],i:['≥ 6.5% (48 mmol/mol) diagnostic of diabetes (confirm); 5.7–6.4% prediabetes','Falsely low: haemolysis, sickle cell disease, recent bleeding or transfusion, pregnancy','Falsely high: iron deficiency anaemia'],ref:['ada','ngsp']},
'Renal function tests':{p:'Urea: urease/GLDH kinetic method. Creatinine: Jaffe (alkaline picrate) or enzymatic method; enzymatic methods have fewer interferences. eGFR is calculated with the 2021 CKD-EPI equation without race.',r:['Urea (urease–GLDH) reagent','Creatinine Jaffe or enzymatic reagent, IDMS-traceable calibrator','Uric acid (uricase–peroxidase) reagent'],q:['Use IDMS-traceable creatinine calibration','Jaffe interferences: ketones, bilirubin, some cephalosporins'],i:['↑ Urea with normal creatinine: dehydration, GI bleed, high protein intake','↑ Urea and creatinine: acute or chronic kidney injury','↑ Uric acid: gout, tumour lysis, renal failure, thiazides'],ref:['ckdepi','tietz']},
'Electrolytes and minerals':{p:'Na⁺, K⁺, Cl⁻ are measured by ion-selective electrodes (indirect ISE on most analysers). Calcium (arsenazo III/o-cresolphthalein), phosphate (phosphomolybdate) and magnesium (xylidyl blue) are photometric.',r:['ISE reference and calibration solutions','Calcium, phosphate, magnesium reagents and controls'],q:['Check haemolysis index before reporting K⁺','Indirect ISE gives falsely low Na⁺ in severe hyperlipidaemia or hyperproteinaemia (pseudohyponatraemia)'],i:['Hyperkalaemia: renal failure, ACE inhibitors, acidosis; exclude haemolysis and EDTA contamination','Hyponatraemia: SIADH, diuretics, heart/liver failure','Corrected Ca = measured Ca + 0.02 × (40 − albumin g/L) mmol/L'],ref:['payne','tietz']},
'Liver function tests':{p:'ALT and AST: IFCC kinetic methods (with pyridoxal phosphate). ALP: p-nitrophenyl phosphate. Bilirubin: diazo method (direct = conjugated). Albumin: bromocresol green or purple.',r:['IFCC enzyme reagents','Diazo bilirubin reagents','Albumin dye reagent'],q:['Protect bilirubin samples from light','Haemolysis falsely raises AST and LDH'],i:['Hepatocellular pattern: ALT/AST ≫ ALP (hepatitis, drugs, ischaemia)','Cholestatic pattern: ALP and GGT ↑ (obstruction, drugs)','↑ Unconjugated bilirubin: haemolysis, Gilbert syndrome','↓ Albumin: chronic liver disease, nephrotic syndrome, malnutrition'],ref:['tietz']},
'Lipid profile':{p:'Enzymatic methods: cholesterol esterase/oxidase, glycerol-phosphate oxidase for triglycerides, direct homogeneous HDL and LDL assays. LDL can be calculated with the Friedewald equation when TG < 4.5 mmol/L.',r:['Cholesterol, triglyceride, HDL (and direct LDL) reagents','Lipid calibrators and controls'],q:['Fasting needed when TG is high; note fasting status on the report'],i:['↑ LDL-C: major modifiable risk factor for atherosclerosis','↓ HDL-C and ↑ TG: metabolic syndrome, diabetes','Very high TG (> 10 mmol/L) risks acute pancreatitis'],ref:['friedewald','ncep']},
'Cardiac markers':{p:'High-sensitivity cardiac troponin T or I immunoassays detect myocardial injury; diagnosis of myocardial infarction requires a rise and/or fall with at least one value above the 99th percentile upper reference limit plus clinical evidence of ischaemia.',r:['hs-troponin immunoassay reagents and calibrators','CK and CK-MB reagents'],q:['Use the assay-specific 99th percentile URL and sex-specific cut-offs where recommended','Report results in ng/L with time of sampling'],i:['↑ Troponin: MI, myocarditis, pulmonary embolism, sepsis, renal failure (interpret the delta)','CK ↑ also in muscle injury, exercise, rhabdomyolysis'],ref:['udmi4']},
'Pancreatic enzymes':{p:'Amylase: enzymatic method with defined oligosaccharide substrates (e.g. EPS-G7). Lipase: colorimetric enzymatic methods. Amylase is calcium-dependent, so EDTA and citrate interfere.',r:['Amylase and lipase reagents, calibrators, controls'],q:['Use serum or heparin plasma; avoid EDTA and citrate','Lipaemia and haemolysis interfere with some lipase methods'],i:['> 3 × upper reference limit supports acute pancreatitis (with clinical features or imaging)','Lipase is more specific and stays raised longer than amylase','↑ Amylase also in salivary disease, macroamylasaemia, renal failure'],ref:['tietz']},
'Thyroid function tests':{p:'TSH: two-site (sandwich) immunoassay; FT4 and FT3: competitive or analogue immunoassays. TSH is the most sensitive first-line test of primary thyroid dysfunction.',r:['TSH, FT4, FT3 immunoassay reagents, calibrators and controls'],q:['Ask about biotin; heterophile antibodies can cause false results','Use method- and trimester-specific ranges in pregnancy'],i:['↑ TSH, ↓ FT4: primary hypothyroidism','↓ TSH, ↑ FT4/FT3: hyperthyroidism (Graves, toxic nodule, thyroiditis)','↓ TSH with ↓ FT4: central (pituitary) hypothyroidism or non-thyroidal illness'],ref:['tietz','fda_biotin']},
'Cortisol, prolactin and β-hCG':{p:'Immunoassays: competitive for cortisol, sandwich for prolactin and hCG. Cortisol has a strong circadian rhythm (highest in the early morning).',r:['Cortisol, prolactin and β-hCG immunoassay reagents'],q:['Record sample time for cortisol','Screen high prolactin for macroprolactin (PEG precipitation)','Very high hCG may cause a hook effect in some assays'],i:['↓ Morning cortisol: adrenal insufficiency (confirm with stimulation test)','↑ Prolactin: pregnancy, prolactinoma, dopamine antagonists, hypothyroidism','↑ β-hCG: pregnancy, molar pregnancy, germ cell tumours'],ref:['tietz']},
'Urine general examination (GUE)':{p:'Physical examination, reagent-strip chemistry (pH indicators, protein error of indicators, glucose oxidase, nitroprusside for ketones, peroxidase activity of haem, Griess reaction for nitrite, leucocyte esterase) and microscopy of the centrifuged sediment.',r:['Reagent strips (stored dry, in date)','Centrifuge, conical tubes, slides and coverslips','Sternheimer–Malbin stain (optional)'],q:['Examine within 2 hours or refrigerate','Check strips daily with positive and negative controls','Correlate strip with microscopy (blood ↔ RBCs, LE ↔ WBCs, nitrite ↔ bacteria)'],i:['Pyuria ± nitrite: urinary tract infection; sterile pyuria: TB, stones','RBC casts or dysmorphic RBCs: glomerular disease','Haematuria in Sudan: consider Schistosoma haematobium','Glycosuria: diabetes or low renal threshold; ketonuria: DKA, starvation'],ref:['eug','cheesbrough1']},
'24-hour urine protein and albumin/creatinine ratio':{p:'Total protein: turbidimetric or pyrogallol red methods; albumin: immunoturbidimetry. The albumin/creatinine ratio (ACR) corrects for urine concentration on a spot sample.',r:['Urine protein and albumin reagents','24-hour collection containers'],q:['Check completeness with 24-h creatinine output','Prefer first-morning spot ACR; repeat to confirm (2 of 3 samples)'],i:['ACR 3–30 mg/mmol: moderately increased albuminuria (early diabetic kidney disease)','ACR > 30 mg/mmol: severely increased albuminuria','Protein > 3.5 g/24 h: nephrotic-range proteinuria'],ref:['tietz']},
'Urine pregnancy test (hCG)':{p:'Lateral-flow sandwich immunoassay: hCG binds labelled antibody and is captured at the test line; a control line confirms proper flow.',r:['Lateral-flow hCG cassettes'],q:['Read only within the stated window','Check the control line; record lot number','Run external positive/negative controls on new lots'],i:['Positive: pregnancy, recent miscarriage or termination, molar pregnancy, hCG-secreting tumour','False negative: very early pregnancy, dilute urine, hook effect'],ref:['tietz']},
'Stool general examination':{p:'Direct saline mounts show motile trophozoites and ova; iodine stains glycogen and nuclei of cysts; formol-ether concentration increases sensitivity by sedimenting parasites and removing fat and debris.',r:['0.85% saline, Lugol’s iodine','10% formol saline, diethyl ether or ethyl acetate'],q:['Examine liquid stool within 30 minutes','Use a calibrated ocular micrometer for size','Keep a bench atlas for comparison'],i:['E. histolytica trophozoites with ingested RBCs: amoebic dysentery','Giardia cysts/trophozoites: malabsorption, diarrhoea','S. mansoni eggs (lateral spine): intestinal schistosomiasis','Hookworm eggs with anaemia and eosinophilia'],ref:['cheesbrough1']},
'Malaria thick and thin blood films':{p:'Giemsa (Romanowsky) at pH 7.2 stains parasite chromatin red and cytoplasm blue. Thick films lyse red cells to concentrate parasites for detection; thin films keep red cells intact for species identification.',r:['Giemsa stock stain','Buffered water pH 7.2','Absolute methanol (thin film fixation)'],q:['Use pH 7.2 buffer and filtered stain','Examine 100 thick-film fields before reporting negative','Cross-check slides (QA) as per national programme'],i:['P. falciparum rings with gametocytes: report urgently','High parasitaemia (> 2%) or schizonts in peripheral blood suggests severe malaria','Negative film with strong suspicion: repeat every 6–12 hours'],ref:['who_malaria','who_mmqa']},
'Urine for Schistosoma haematobium':{p:'Eggs are shed maximally in urine around midday. Filtration through a membrane or sedimentation concentrates eggs; counting per 10 mL estimates intensity of infection.',r:['Polycarbonate/nylon filters (12–20 µm), syringe and holder','Lugol’s iodine or saline'],q:['Collect terminal urine between 10:00 and 14:00','Mix well before sampling 10 mL'],i:['Light infection 1–49 eggs/10 mL; heavy ≥ 50 eggs/10 mL','Chronic infection: bladder fibrosis, obstructive uropathy, squamous cell carcinoma'],ref:['who_schisto','cheesbrough1']},
'Gram stain':{p:'Crystal violet–iodine complexes form inside all bacteria. Gram-positive cells keep the complex because their thick peptidoglycan dehydrates and shrinks with acetone-alcohol; Gram-negative cells lose it through the thin peptidoglycan and outer membrane and take the red counterstain.',r:['Crystal violet','Gram’s iodine (mordant)','Acetone-alcohol decolouriser','Safranin or neutral red'],q:['Stain known Gram-positive (S. aureus) and Gram-negative (E. coli) control smears','Avoid thick smears and over-decolourisation'],i:['Gram-positive cocci in clusters: staphylococci; in chains: streptococci','Gram-negative diplococci in neutrophils (urethral, CSF): Neisseria','Gram-negative rods: Enterobacterales, Pseudomonas'],ref:['cheesbrough2']},
'Ziehl–Neelsen stain (AFB)':{p:'Mycolic acids in the mycobacterial cell wall retain hot carbol fuchsin and resist decolourisation with acid-alcohol (acid-fastness); the background takes methylene blue.',r:['Carbol fuchsin (basic fuchsin + phenol)','3% acid-alcohol or 25% sulphuric acid','Methylene blue counterstain'],q:['Positive and negative control smears with each batch','Use new slides; never reuse slides for AFB','Blinded rechecking (EQA) of a sample of slides'],i:['Grading (IUATLD/WHO): scanty, 1+, 2+, 3+ reflects bacillary load','A positive smear needs Xpert MTB/RIF or culture for resistance testing'],ref:['iuatld','cheesbrough2']},
'Urine culture and colony count':{p:'A calibrated loop delivers a known volume of urine; counting colonies estimates CFU/mL. The classic threshold of ≥ 10⁵ CFU/mL of one organism defines significant bacteriuria in a clean-catch midstream sample.',r:['CLED agar (or blood + MacConkey agar)','Calibrated loops (1 µL or 10 µL)'],q:['Check loop calibration and media performance with control strains','Culture within 2 hours or refrigerate'],i:['≥ 10⁵ CFU/mL single organism: significant bacteriuria','Lower counts can be significant in symptomatic patients, catheter samples and men','≥ 3 organisms: contamination'],ref:['kass','cheesbrough2']},
'Blood culture':{p:'Organisms in blood multiply in enriched broth; automated systems detect CO₂ production; positive bottles are Gram-stained and subcultured. Volume of blood is the most important determinant of yield.',r:['Aerobic and anaerobic blood culture bottles','Chlorhexidine-alcohol skin antiseptic'],q:['Monitor contamination rate (target < 3%)','Fill bottles with the correct volume; two sets before antibiotics'],i:['Growth in multiple sets of a pathogen: bacteraemia','Coagulase-negative staphylococci in one bottle: usually contamination'],ref:['clsi_m47','cheesbrough2']},
'Antimicrobial susceptibility test (Kirby–Bauer disc diffusion)':{p:'An antibiotic diffuses from a paper disc into agar, creating a concentration gradient; the zone of inhibition diameter correlates inversely with the MIC and is interpreted against breakpoints.',r:['Mueller–Hinton agar (4 mm depth)','Antibiotic discs; 0.5 McFarland standard','Quality control strains (e.g. E. coli ATCC 25922, S. aureus ATCC 25923)'],q:['Zone sizes of QC strains must fall within published ranges','Use current CLSI or EUCAST tables only'],i:['S: likely to respond to standard dosing; R: likely treatment failure','Detect and report resistance mechanisms (ESBL, MRSA) as per guidelines'],ref:['bauer','clsi_ast','eucast']},
'C-reactive protein (CRP)':{p:'CRP is an acute-phase protein made by the liver under IL-6 stimulation; it is measured by latex-enhanced immunoturbidimetry.',r:['CRP immunoturbidimetric reagent, calibrator and controls'],q:['Watch for antigen excess (prozone) at very high values on some methods'],i:['Bacterial infection and inflammation raise CRP within 6–8 hours','Serial values help monitor treatment response'],ref:['tietz']},
'Rapid tests: HBsAg, HCV antibody, HIV':{p:'Lateral-flow immunochromatographic assays: HBsAg is detected with antibodies (sandwich); anti-HCV and anti-HIV antibodies are detected with recombinant antigens.',r:['Validated rapid test kits stored as instructed'],q:['Use external controls on each new lot and new operator','Follow the national testing algorithm before reporting HIV positive'],i:['HBsAg reactive: current HBV infection (acute or chronic)','Anti-HCV reactive: past or current infection; confirm with HCV RNA','HIV reactive on one test is not a diagnosis'],ref:['who_hiv']},
'Widal test (typhoid)':{p:'Agglutination of Salmonella O (somatic) and H (flagellar) antigens by patient antibodies; titres are estimated by doubling dilutions.',r:['Stained O, H, AH, BH antigen suspensions','Positive and negative control sera'],q:['Know the local baseline titre of healthy people','Prefer paired sera'],i:['A fourfold rise in paired sera supports enteric fever','Single titres are unreliable: prior infection, vaccination and cross-reaction cause false positives; blood culture is the reference'],ref:['who_typhoid']},
'Brucella serology':{p:'Rose Bengal is a buffered (pH 3.6) antigen screening test; the standard agglutination test (SAT) titrates agglutinating antibodies.',r:['Rose Bengal antigen','SAT antigen, saline, positive and negative control sera'],q:['Use standardised antigen; read SAT end point at 50% agglutination'],i:['SAT ≥ 1:160 is significant in endemic areas (with clinical features)','Prozone can give false negatives at low dilutions; culture confirms'],ref:['who_brucella']},
'ASO and rheumatoid factor':{p:'Latex particles coated with streptolysin O (ASO) or human IgG (RF) agglutinate in the presence of the corresponding antibodies; quantitative turbidimetry is also used.',r:['ASO and RF latex reagents or turbidimetric reagents','Positive and negative controls'],q:['Read within the stated time; prozone at very high titres'],i:['↑ ASO: recent streptococcal infection (rheumatic fever, post-streptococcal glomerulonephritis)','↑ RF: rheumatoid arthritis, Sjögren syndrome, chronic infection; not specific'],ref:['tietz']},
'rK39 test (visceral leishmaniasis / kala-azar)':{p:'Immunochromatographic detection of antibodies against recombinant K39 kinesin antigen of L. donovani complex.',r:['rK39 rapid test kits and buffer'],q:['Store kits correctly; check control line'],i:['Positive with compatible clinical features supports visceral leishmaniasis','Antibodies persist after cure: not useful for relapse; parasitology confirms'],ref:['who_leish']},
'ABO and Rh(D) grouping (tube method)':{p:'Haemagglutination: red cell antigens are detected by antisera (forward group) and plasma antibodies by reagent cells (reverse group). Results must agree.',r:['Anti-A, anti-B, anti-D (monoclonal) reagents','A₁ and B reagent red cells','Normal saline, centrifuge, tubes'],q:['Daily reagent QC with known cells','Resolve all forward/reverse discrepancies before issuing','Second independent group on a separate sample before first transfusion (where policy requires)'],i:['Discrepancies: weak subgroups, elderly or infants, cold agglutinins, recent transfusion'],ref:['aabb','bsh_pt']},
'Crossmatch (antiglobulin method)':{p:'Detects antibodies in patient plasma that react with donor red cells, including IgG antibodies that need anti-human globulin to cause visible agglutination.',r:['LISS, polyspecific or anti-IgG AHG','IgG-coated control cells'],q:['Validate every negative AHG test with control cells','Use a sample of the right age (≤ 72 h if recently transfused or pregnant)'],i:['Incompatibility: alloantibody, autoantibody or wrong unit; never issue incompatible blood without senior review'],ref:['aabb','bsh_pt']},
'Direct antiglobulin test (DAT / direct Coombs)':{p:'AHG detects IgG and/or complement already bound to the patient’s red cells in vivo.',r:['Polyspecific AHG; monospecific anti-IgG and anti-C3d for positive results','IgG-coated control cells'],q:['Wash cells thoroughly; test promptly'],i:['Positive: autoimmune haemolytic anaemia, haemolytic disease of the newborn, haemolytic transfusion reaction, some drugs'],ref:['aabb']},
'Specimen reception, fixation and grossing':{p:'Formaldehyde fixes tissue by forming methylene bridges between proteins; it penetrates quickly but fixes slowly, so adequate time and volume are essential.',r:['10% neutral buffered formalin','Tissue inks, cassettes, grossing instruments'],q:['Record cold ischaemia and total fixation time (ASCO/CAP for breast)','Two-identifier checks at reception and grossing'],i:['Inadequate fixation causes poor morphology and false-negative ER/PR/HER2'],ref:['bancroft','asco_cap']},
'Tissue processing (overnight schedule)':{p:'Water is removed by graded alcohols (dehydration), alcohol by a clearing agent miscible with wax (xylene), and the tissue is infiltrated with molten paraffin wax to support sectioning.',r:['Graded ethanol, xylene (or substitute), paraffin wax'],q:['Change reagents on a fixed schedule; monitor wax temperature'],i:['Poor processing shows as crumbling, holes or hard brittle blocks'],ref:['bancroft']},
'Embedding and microtomy':{p:'Correct orientation in the block determines which planes are seen; thin, flat sections allow clear morphology and IHC.',r:['Paraffin wax, moulds, cold plate','Microtome and disposable blades','Water bath, charged slides'],q:['Check full-face sections and ribbon quality','Clean the water bath between cases to avoid floaters (cross-contamination)'],i:['Artefacts (chatter, folds, floaters) can mimic or hide lesions'],ref:['bancroft']},
'Haematoxylin and eosin (H&E) staining':{p:'Haematoxylin is oxidised to haematein and used with an aluminium mordant (haemalum), which binds nuclear chromatin (phosphate groups of DNA); bluing converts it to an insoluble blue. Eosin, an acidic dye, binds basic proteins in cytoplasm and connective tissue.',r:['Harris or Mayer haematoxylin','1% acid-alcohol; Scott’s tap water substitute','Eosin Y'],q:['Run a control slide each batch','Filter haematoxylin daily; monitor eosin strength'],i:['Crisp nuclear detail is the basis of diagnosis of neoplasia and inflammation'],ref:['bancroft']},
'Frozen section (intra-operative)':{p:'Water in fresh tissue is frozen to harden it for cutting in a cryostat, allowing a rapid diagnosis during surgery.',r:['OCT embedding medium, cryostat, rapid H&E reagents'],q:['Measure turnaround time (CAP benchmark: 90% within 20 minutes)','Correlate every frozen diagnosis with the permanent section'],i:['Uses: margins, malignancy yes/no, adequacy of lesional tissue; fat and bone are difficult'],ref:['novis','bancroft']},
'Decalcification of bone and calcified tissue':{p:'Acids dissolve calcium salts; chelating agents (EDTA) bind calcium ions slowly but preserve antigens and nucleic acids.',r:['Formic acid 5–10%','EDTA 10–14% pH 7.0–7.4','Strong mineral acids (HCl, nitric)'],q:['Test the end point daily; avoid over-decalcification'],i:['EDTA is preferred when IHC or molecular tests are needed'],ref:['bancroft']},
'PAS and PAS-diastase':{p:'Periodic acid oxidises 1,2-glycol groups of carbohydrates to aldehydes, which react with Schiff reagent to give a magenta colour. Diastase digests glycogen, so glycogen is PAS-positive but PAS-D negative.',r:['0.5–1% periodic acid','Schiff reagent','Diastase (or α-amylase)'],q:['Control: liver or kidney; diastase control confirms enzyme activity'],i:['Glycogen storage, fungi, basement membranes, α1-antitrypsin globules (PAS-D positive), Whipple disease macrophages'],ref:['bancroft']},
'Ziehl–Neelsen for tissue (AFB) and Wade–Fite':{p:'Same acid-fast principle as smears. M. leprae is less acid-fast, so the Wade–Fite method protects the lipid coat (oil–xylene dewaxing) and uses a gentler decolouriser.',r:['Carbol fuchsin','Acid-alcohol (ZN) or weak sulphuric acid (Wade–Fite)','Methylene blue'],q:['Known positive tissue control with each batch'],i:['AFB in granulomas: tuberculosis or atypical mycobacteria','Globi in macrophages: lepromatous leprosy'],ref:['bancroft','fite']},
'Masson trichrome':{p:'Dyes of different molecular size compete for tissue sites; phosphomolybdic/phosphotungstic acid removes red dye from collagen, which then takes aniline blue (or light green).',r:['Bouin’s fluid (mordant)','Weigert’s iron haematoxylin','Biebrich scarlet–acid fuchsin','Phosphomolybdic/phosphotungstic acid','Aniline blue'],q:['Control: skin or liver'],i:['Grades fibrosis in liver, kidney and heart; separates collagen from smooth muscle'],ref:['bancroft']},
'Perls’ Prussian blue (iron)':{p:'Hydrochloric acid releases ferric iron from haemosiderin, which reacts with potassium ferrocyanide to form insoluble ferric ferrocyanide (Prussian blue).',r:['2% potassium ferrocyanide','2% hydrochloric acid','Nuclear fast red'],q:['Iron-free glassware and water; known positive control'],i:['Haemochromatosis, haemosiderosis, bone marrow iron stores, sideroblasts'],ref:['bancroft']},
'Congo red (amyloid)':{p:'Congo red molecules align along the β-pleated sheet fibrils of amyloid; ordered dye gives apple-green birefringence under crossed polarisers.',r:['Alkaline sodium chloride solution','Alkaline Congo red (Puchtler method)','Haematoxylin'],q:['Cut 8–10 µm sections; known amyloid control','Use properly aligned polariser and analyser'],i:['Systemic AL, AA and ATTR amyloidosis; typing needs IHC or mass spectrometry'],ref:['puchtler','bancroft']},
'Grocott methenamine silver (fungi)':{p:'Chromic acid oxidises polysaccharides in fungal walls to aldehydes, which reduce methenamine silver to black metallic silver.',r:['5% chromic acid','Sodium metabisulphite','Methenamine silver working solution','Gold chloride, sodium thiosulphate, light green'],q:['Fungal control slide checked microscopically during silver step','Acid-cleaned glassware'],i:['Fungi (Aspergillus, Candida, Histoplasma, Madurella in mycetoma) and Pneumocystis'],ref:['grocott','bancroft']},
'Alcian blue (pH 2.5) and AB-PAS':{p:'At pH 2.5 the cationic dye binds carboxylated and sulphated acid mucins; at pH 1.0 only sulphated mucins stain. AB-PAS separates acid (blue) from neutral (magenta) mucins.',r:['Alcian blue 8GX in 3% acetic acid (pH 2.5)','Periodic acid, Schiff reagent','Nuclear fast red or haematoxylin'],q:['Control: small intestine or colon'],i:['Goblet cells of intestinal metaplasia (Barrett oesophagus, stomach); mucinous tumours'],ref:['bancroft']},
'Antibody screen (indirect antiglobulin test)':{p:'Patient plasma is incubated at 37 °C with reagent red cells of known antigen types. IgG antibodies that bind are detected by anti-human globulin, which links the coated cells and makes them agglutinate.',r:['Group O screening cells (2–3 cells) with antigram','LISS (low ionic strength solution)','Polyspecific or anti-IgG anti-human globulin','IgG-coated control cells','Weak anti-D control serum'],q:['Weak anti-D positive and negative controls in each batch','Control cells added to every negative tube test','Validated centrifuge timing and cell concentration'],i:['Pre-transfusion testing','Antenatal screening for antibodies that cause haemolytic disease of the fetus and newborn','Investigation of transfusion reactions'],ref:['bsh_pt','aabb']},
'Haemoglobin electrophoresis and HbA2 / HbF quantitation':{p:'Amino-acid substitutions change the electrical charge of haemoglobin variants, so they move at different speeds in an electric field (electrophoresis); HPLC separates the same fractions on a cation-exchange column and measures each one.',r:['Alkaline buffer (Tris-EDTA-borate, pH 8.4–8.6) and cellulose acetate strips','Citrate agar buffer, pH about 6.0–6.3','Protein stain (e.g. Ponceau S)','HPLC or capillary electrophoresis analyser with its controls'],q:['Normal and abnormal (A, F, S, C) controls in every run','Confirm every variant by a second method','External quality assessment'],i:['Sickle cell disease and sickle trait; HbC, HbD and HbE','β-thalassaemia trait (raised HbA2); raised HbF in δβ-thalassaemia and hereditary persistence of fetal haemoglobin','Antenatal, premarital and family screening'],ref:['bsh_hbp','dacie','bain_hbp']},
'Von Kossa (calcium salts)':{p:'Silver ions replace the calcium bound to phosphate and carbonate in calcium salts, and light reduces the silver salt to black metallic silver; sodium thiosulphate then removes unreacted silver. The method shows the anions of calcium salts, so it is not specific for calcium itself (Alizarin red S is the calcium-specific alternative).',r:['5% silver nitrate','5% sodium thiosulphate','Nuclear fast red','Ultraviolet lamp or 100 W incandescent lamp'],q:['Known calcified control with each run','Acid-cleaned glassware and distilled water','Never use decalcified tissue or acid fixatives'],i:['Dystrophic and metastatic calcification','Michaelis–Gutmann bodies in malakoplakia','Psammoma bodies; calcification in breast, prostate, vessels and kidney'],ref:['bancroft','abcam_vk']},
'Giemsa for Helicobacter pylori (gastric biopsy)':{p:'Giemsa is a Romanowsky stain (methylene blue, azure and eosin). The bacteria take up the basic thiazine dyes and, after brief acid differentiation, stand out blue against a pale purple background.',r:['Jenner’s stain (working 1 : 1 with distilled water)','Giemsa stock (working: 2.4 mL in 50 mL distilled water)','Methanol','0.1% acetic acid','tert-butyl or absolute alcohol'],q:['Known H. pylori-positive gastric control in each run','Fresh working solutions; working Giemsa is not reused','Differentiate one slide at a time under the microscope'],i:['Helicobacter pylori gastritis: chronic active gastritis, peptic ulcer, and the risk of gastric adenocarcinoma and MALT lymphoma'],ref:['ems_giemsa','bancroft']},
'Tissue Gram stain (Brown–Hopps)':{p:'Crystal violet–iodine complexes stay in the thick peptidoglycan wall of Gram-positive bacteria after decolorisation; Gram-negative bacteria lose them and take up basic fuchsin. Gallego’s solution differentiates and fixes the fuchsin, and tartrazine stains the background yellow.',r:['1% crystal violet','Gram’s iodine','Cellosolve (2-ethoxyethanol)','0.5% basic fuchsin','Gallego’s solution','1.5% tartrazine'],q:['Control containing both Gram-positive and Gram-negative bacteria','Time the decolorising, rinsing and tartrazine steps exactly','Not suitable for Bouin-fixed tissue'],i:['Actinomycosis (sulphur granules) and Nocardia','Bacterial grains of actinomycetoma','Bacteria in abscesses, vegetations and necrotic tissue'],ref:['luna_afip','ems_bh','bancroft']},
'Reticulin (Gordon and Sweet)':{p:'Reticulin fibres (type III collagen) are argyrophilic: after oxidation and sensitisation, they bind ammoniacal silver, which is reduced to black metallic silver.',r:['Acidified potassium permanganate, oxalic acid','Iron alum, ammoniacal silver','Formalin, gold chloride, sodium thiosulphate'],q:['Acid-cleaned glassware; fresh ammoniacal silver (never store)'],i:['Liver: collapse vs fibrosis, thickened plates in hepatocellular carcinoma; bone marrow fibrosis grading'],ref:['bancroft']},
'Immunohistochemistry (IHC), polymer method':{p:'A primary antibody binds its antigen in tissue; an enzyme-labelled polymer detection system and a chromogen (DAB) produce a brown insoluble product at the antigen site. Heat-induced epitope retrieval reverses formalin cross-links.',r:['Retrieval buffers (citrate pH 6.0, Tris-EDTA pH 9.0)','3% hydrogen peroxide','Primary antibodies, polymer–HRP, DAB','Haematoxylin counterstain'],q:['Positive and negative controls on every slide or run','Validate every new antibody and clone','External QA (e.g. NordiQC/UK NEQAS)'],i:['Tumour typing (e.g. cytokeratins vs lymphoid markers), prognostic and predictive markers (ER, PR, HER2, Ki-67)'],ref:['bancroft','asco_cap']},
'Smear preparation and fixation':{p:'Immediate alcohol fixation preserves nuclear chromatin for Pap staining; rapid air drying preserves cytoplasm and background for Romanowsky stains.',r:['95% ethanol or spray fixative','Clean frosted slides, pencil'],q:['Label slides before collection','Check smear thickness and fixation on screening'],i:['Air-drying artefact in Pap smears (enlarged pale nuclei) can mimic atypia'],ref:['gill']},
'Fine-needle aspiration (FNA) technique':{p:'Capillary action and/or suction draw cells into a fine needle moving through the lesion; the sample allows rapid, minimally invasive diagnosis.',r:['22–25 G needles, syringes and holder','Slides, 95% ethanol, saline/preservative for cell block'],q:['Rapid on-site evaluation to confirm adequacy','Correlate with imaging and clinical findings'],i:['Diagnostic accuracy depends on sampling and preparation as much as on interpretation'],ref:['gill','bethesda_thy']},
'Papanicolaou (Pap) stain':{p:'Polychrome stain: haematoxylin for nuclei; OG-6 (orange G) stains keratin; EA (eosin azure: light green, eosin Y, Bismarck brown) stains cytoplasm by degree of maturation. Transparent staining lets overlapping cells be seen.',r:['Harris haematoxylin','OG-6','EA-50 (or EA-65)','Graded alcohols, xylene'],q:['Filter stains daily; separate staining lines for gynae and non-gynae','Check colour balance on a control slide'],i:['Nuclear detail allows grading of squamous and glandular lesions'],ref:['gill','bethesda_cx']},
'May-Grünwald-Giemsa (MGG) and Diff-Quik':{p:'Romanowsky stains on air-dried smears: cytoplasm, granules and extracellular material (colloid, mucin, matrix) stain well, some metachromatically.',r:['May-Grünwald and Giemsa stains, buffer pH 6.8','Diff-Quik fixative and solutions I and II'],q:['Use buffer at pH 6.8; replace rapid stains regularly'],i:['Metachromatic matrix suggests pleomorphic adenoma; lymphoid cells are best typed on air-dried smears'],ref:['gill']},
'Liquid-based cytology (ThinPrep / SurePath)':{p:'Cells are collected into a preservative fluid; the processor reduces blood, mucus and debris and deposits a thin layer of cells on a defined area of the slide.',r:['Manufacturer’s preservative vials and processor','Pap stain'],q:['Follow manufacturer instructions exactly; record unsatisfactory rates'],i:['Residual fluid allows HPV testing (reflex or co-testing)'],ref:['bethesda_cx','gill']},
'Cytocentrifuge (Cytospin) preparation':{p:'Low-speed centrifugation deposits cells from a small fluid volume onto a defined slide area while the filter card absorbs fluid.',r:['Cytocentrifuge, chambers, filter cards','Albumin (for protein-poor fluids)'],q:['Process CSF promptly; check cell distribution and morphology'],i:['Essential for low-cellularity fluids such as CSF'],ref:['gill']},
'Sputum and bronchial cytology':{p:'Exfoliated cells from the lower respiratory tract are concentrated and examined; alveolar macrophages prove the sample came from the lungs.',r:['Wide-mouthed containers; 50% ethanol (Saccomanno-type) fixative if delayed','Pap stain'],q:['Reject saliva-only samples (no macrophages)'],i:['Squamous carcinoma (keratinised cells), adenocarcinoma, small cell carcinoma; fungi; viral changes'],ref:['who_lung','gill']},
'Cell block preparation':{p:'Concentrating cells into a formalin-fixed paraffin block allows multiple sections for morphology, IHC and molecular testing.',r:['Plasma–thrombin, agar or HistoGel','Lens paper, cassettes, 10% NBF'],q:['Fix for at least 6 hours (ASCO/CAP for ER/PR)'],i:['Key for typing metastatic tumours in effusions and FNAs'],ref:['bancroft','asco_cap']},
'Normal cells – identification guide':{p:'Recognising the full range of normal and reactive cells is the basis of every cytological diagnosis.',r:['Bench atlas; ocular micrometer'],q:['Regular review of difficult cases with the cytopathologist'],i:['Report normal endometrial cells in women aged ≥ 45 years (Bethesda)'],ref:['bethesda_cx','gill']},
'Quality control in cytology':{p:'Cytology QA combines laboratory QC (stains, preparation), screening QC (rescreening, workload limits), and outcome audit (cytology–histology correlation).',r:['QC logs, rescreening records, correlation database'],q:['Rescreen ≥ 10% of negative gynaecological slides','Respect workload limits (CLIA reference: ≤ 100 slides in no less than 8 h per 24 h)'],i:['High false-negative rates trigger retraining and workload review'],ref:['clia','bethesda_cx']},
'Cytological criteria of malignancy':{p:'Malignant cells show genetic instability reflected mainly in nuclear features: enlargement, high N:C ratio, hyperchromasia, irregular membranes and abnormal chromatin and nucleoli.',r:['Well-stained Pap and Romanowsky preparations'],q:['Compare with the normal counterpart cell; seek second opinion on difficult cases'],i:['Several criteria together are needed; reactive and repair changes are the main mimics'],ref:['gill','bethesda_cx']},
'Cervical cytology – Bethesda System':{p:'The Bethesda System provides uniform terminology: specimen adequacy, general categorisation and interpretation/result, linked to management guidelines.',r:['Pap-stained conventional or LBC slides'],q:['Track ASC:SIL ratio and unsatisfactory rates'],i:['NILM: routine screening; ASC-US: HPV triage; LSIL/HSIL: colposcopy per guidelines'],ref:['bethesda_cx']},
'Squamous and glandular lesions – diagnostic criteria':{p:'HPV infection causes cytopathic changes (koilocytes) in mature cells (LSIL); progression shows immature cells with high N:C ratios (HSIL).',r:['Pap-stained slides'],q:['Use the intermediate nucleus as a size reference consistently'],i:['HSIL corresponds to CIN 2–3 and needs colposcopic evaluation'],ref:['bethesda_cx']},
'Thyroid FNA – Bethesda System':{p:'Six diagnostic categories, each linked to an implied risk of malignancy and recommended management; the 3rd edition (2023) uses a single name for each category.',r:['Air-dried and Pap-stained smears; cell block if available'],q:['Monitor category distribution (AUS rate) and correlate with histology'],i:['Category II: follow-up; VI: surgery; III–IV: repeat FNA, molecular testing or lobectomy'],ref:['bethesda_thy']},
'Breast FNA – IAC Yokohama System':{p:'Five categories with risk of malignancy and management recommendations, used within the triple test (clinical, imaging, pathology).',r:['Air-dried and Pap-stained smears'],q:['Correlate with imaging and core biopsy outcomes'],i:['Atypical and suspicious categories need core needle biopsy'],ref:['yokohama']},
'Salivary gland FNA – Milan System':{p:'Six main categories (with Neoplasm subdivided into benign and SUMP) stratify risk of malignancy and guide management.',r:['MGG and Pap smears; cell block for ancillary tests'],q:['Use ancillary IHC/molecular tests for matrix-rich and basaloid neoplasms'],i:['Pleomorphic adenoma and Warthin tumour are the commonest benign neoplasms'],ref:['milan']},
'Lymph node FNA – Sydney System':{p:'A two-level system: five cytological categories, refined by ancillary tests (flow cytometry, IHC, molecular, microbiology).',r:['Air-dried and Pap smears; samples for flow cytometry, culture and cell block'],q:['Send material for ZN/culture when granulomas or necrosis are seen'],i:['Lymphoma usually requires flow cytometry and/or excision biopsy for classification'],ref:['sydney']},
'Serous effusion cytology – International System':{p:'Five diagnostic categories with risk of malignancy; ancillary IHC on cell blocks separates mesothelial from epithelial cells.',r:['Smears, cytospins and cell block; IHC panel'],q:['Process at least 50–100 mL when possible; prepare a cell block'],i:['Malignant effusion indicates advanced-stage disease; identify primary site with IHC'],ref:['issfc']},
'Urine cytology – Paris System':{p:'The Paris System focuses on detecting high-grade urothelial carcinoma, using the N:C ratio as a key criterion along with hyperchromasia, irregular membrane and coarse chromatin.',r:['Cytospin or LBC slides, Pap stain'],q:['Avoid first-morning urine (degenerated cells)'],i:['HGUC/SHGUC need cystoscopy and biopsy; low-grade lesions are poorly detected by cytology'],ref:['paris']},
'CSF cytology':{p:'Cytospin preparations of CSF detect malignant cells (leukaemia, lymphoma, metastatic carcinoma) and inflammatory cells.',r:['Cytocentrifuge, MGG and Pap stains'],q:['Process within 1 hour; record volume and cell count'],i:['Neutrophils: bacterial meningitis; lymphocytes: viral, TB, fungal meningitis; blasts: CNS leukaemia'],ref:['gill']},
'Respiratory cytology – WHO System':{p:'Five categories applicable to all respiratory specimens, each with risk of malignancy and management advice; material should be preserved for ancillary and molecular tests.',r:['Pap and Romanowsky stains; cell block; IHC (TTF-1, p40)'],q:['Report adequacy; preserve material for molecular testing'],i:['Typing (adenocarcinoma vs squamous vs small cell) directs therapy'],ref:['who_lung']}
};

